select id, log_ts, level, latency_ms, status_code, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier as tier, coalesce(context['version'], 'unknown') as version_or_default, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries as retry_count, get_json_object(payload_json, '$.user.tier') as user_tier, context['region'] as region from app_logs
